def _compute_show_check_availability(self):
    """ According to `picking.show_check_availability`, the "Reserve" button will be
    displayed in the form view of a picking.
    """
    for picking in self:
        if picking.state not in ('confirmed', 'waiting', 'assigned'):
            picking.show_check_availability = False
            continue
        if all(m.picked or m.product_uom_qty == m.quantity for m in picking.move_ids):
            picking.show_check_availability = False
            continue
        picking.show_check_availability = any(
            move.state in ('waiting', 'confirmed', 'partially_available') and
            move.uom_id.compare(move.product_uom_qty, 0)
            for move in picking.move_ids
        )

def _compute_validate_button_style(self):
    for picking in self:
        if picking.state in ('done', 'cancel'):
            picking.validate_button_style = 'invisible'
        elif picking.state in ('waiting', 'assigned'):
            picking.validate_button_style = 'primary'
        else:
            picking.validate_button_style = 'secondary'

def _check_move_lines_map_quant_package(self, package):
    return package._check_move_lines_map_quant(self.move_line_ids.filtered(lambda ml:
        ml.product_id.is_storable
        and (ml.package_id == package or ml.package_id in package.all_children_package_ids)))

def _check_entire_pack(self):
    """ This function check if entire packs are moved in the picking"""
    for package, package_move_lines in self.move_line_ids.grouped('package_id').items():
        if not package:
            continue
        pickings = package_move_lines.picking_id
        if pickings._is_single_transfer() and pickings._check_move_lines_map_quant_package(package):
            move_lines_to_pack = package_move_lines.filtered(lambda ml: not ml.result_package_id and ml.state not in ('done', 'cancel'))
            if package.package_type_id.package_use != 'reusable':
                move_lines_to_pack.write({
                    'result_package_id': package.id,
                    'is_entire_pack': True,
                })
    # If we move all packages within a package, we can consider that they keep their container as well
    self.move_line_ids.result_package_id._apply_package_dest_for_entire_packs()

def _get_lot_move_lines_for_sanity_check(self, none_done_picking_ids, separate_pickings=True):
    """ Get all move_lines with tracked products that need to be checked over in the sanity check.
        :param none_done_picking_ids: Set of all pickings ids that have no quantity set on any move_line.
        :param separate_pickings: Indicates if pickings should be checked independently for lot/serial numbers or not.
    """
    def get_relevant_move_line_ids(none_done_picking_ids, picking):
        # Get all move_lines if picking has no quantity set, otherwise only get the move_lines with some quantity set.
        if picking.id in none_done_picking_ids:
            return picking.move_line_ids.filtered(lambda ml: ml.product_id and ml.product_id.tracking in ['lot', 'serial']).ids
        else:
            return get_line_with_done_qty_ids(picking.move_line_ids)

    def get_line_with_done_qty_ids(move_lines):
        # Get only move_lines that has some quantity set.
        return move_lines.filtered(lambda ml: ml.product_id.tracking in ['lot', 'serial'] and ml.picked and ml.uom_id.compare(ml.quantity, 0)).ids

    if separate_pickings:
        # If pickings are checked independently, get full/partial move_lines depending if each picking has no quantity set.
        lines_to_check_ids = [line_id for picking in self for line_id in get_relevant_move_line_ids(none_done_picking_ids, picking)]
    else:
        # If pickings are checked as one (like in a batch), then get only the move_lines with quantity across all pickings if there is at least one.
        if any(picking.id not in none_done_picking_ids for picking in self):
            lines_to_check_ids = get_line_with_done_qty_ids(self.move_line_ids)
        else:
            lines_to_check_ids = self.move_line_ids.filtered(lambda ml: ml.product_id and ml.product_id.tracking in ['lot', 'serial']).ids

    return self.env['stock.move.line'].browse(lines_to_check_ids)

def _sanity_check(self, separate_pickings=True):
    """ Sanity check for `button_validate()`
        :param separate_pickings: Indicates if pickings should be checked independently for lot/serial numbers or not.
    """
    pickings_without_lots = self.browse()
    products_without_lots = self.env['product.product']
    pickings_without_moves = self.filtered(lambda p: not p.move_ids and not p.move_line_ids)
    precision_digits = self.env['decimal.precision'].precision_get('Product Unit')

    no_quantities_done_ids = set()
    pickings_without_quantities = self.env['stock.picking']
    for picking in self:
        has_pick = any(move.picked and move.state not in ('done', 'cancel') for move in picking.move_ids)
        if all(float_is_zero(move.quantity, precision_digits=precision_digits) for move in picking.move_ids.filtered(lambda m: m.state not in ('done', 'cancel') and (not has_pick or m.picked))):
            pickings_without_quantities |= picking

    pickings_using_lots = self.filtered(lambda p: p.picking_type_id.use_create_lots or p.picking_type_id.use_existing_lots)
    if pickings_using_lots:
        lines_to_check = pickings_using_lots._get_lot_move_lines_for_sanity_check(no_quantities_done_ids, separate_pickings)
        for line in lines_to_check:
            if not line.lot_name and not line.lot_id:
                pickings_without_lots |= line.picking_id
                products_without_lots |= line.product_id

    if not self._should_show_transfers():
        if pickings_without_moves:
            raise UserError(_("You can’t validate an empty transfer. Please add some products to move before proceeding."))
        if pickings_without_quantities:
            raise UserError(self._get_without_quantities_error_message())
        if pickings_without_lots:
            raise UserError(_('You need to supply a Lot/Serial number for products %s.', ', '.join(products_without_lots.mapped('display_name'))))
    else:
        message = ""
        if pickings_without_moves:
            message += _('Transfers %s: Please add some items to move.', ', '.join(pickings_without_moves.mapped('name')))
        if pickings_without_lots:
            message += _(
                '\n\nTransfers %(transfer_list)s: You need to supply a Lot/Serial number for products %(product_list)s.',
                transfer_list=pickings_without_lots.mapped('name'),
                product_list=products_without_lots.mapped('display_name'),
            )
        if message:
            raise UserError(message.lstrip())

def button_validate(self):
    self = self.filtered(lambda p: p.state != 'done')
    draft_picking = self.filtered(lambda p: p.state == 'draft')
    res = draft_picking.with_context(to_validate=True).action_confirm()
    if res is not True:
        return res
    for move in draft_picking.move_ids:
        if move.uom_id.is_zero(move.quantity) and not move.uom_id.is_zero(move.product_uom_qty):
            move.quantity = move.product_uom_qty

    # Sanity checks.
    if not self.env.context.get('skip_sanity_check', False):
        self._sanity_check()

    # Run the pre-validation wizards. Processing a pre-validation wizard should work on the
    # moves and/or the context and never call `_action_done`.
    if not self.env.context.get('button_validate_picking_ids'):
        self = self.with_context(button_validate_picking_ids=self.ids)
    res = self._pre_action_done_hook()
    if res is not True:
        return res

    # Call `_action_done`.
    pickings_not_to_backorder = self.filtered(lambda p: p.picking_type_id.create_backorder == 'never')
    if self.env.context.get('picking_ids_not_to_backorder'):
        pickings_not_to_backorder |= self.browse(self.env.context['picking_ids_not_to_backorder']).filtered(
            lambda p: p.picking_type_id.create_backorder != 'always'
        )
    pickings_to_backorder = self - pickings_not_to_backorder
    if pickings_not_to_backorder:
        pickings_not_to_backorder.with_context(cancel_backorder=True)._action_done()
    if pickings_to_backorder:
        pickings_to_backorder.with_context(cancel_backorder=False)._action_done()

    # Remove done pickings from their batch.
    if any(picking.state == 'done' for picking in self):
        to_assign_ids = set()
        if self and self.env.context.get('pickings_to_detach'):
            pickings_to_detach = self.env['stock.picking'].browse(self.env.context['pickings_to_detach'])
            pickings_to_detach.batch_id = False
            pickings_to_detach.move_ids.filtered(lambda m: not m.quantity).picked = False
            to_assign_ids.update(self.env.context['pickings_to_detach'])

        for picking in self:
            if picking.state != 'done':
                continue
            # Avoid inconsistencies in states of the same batch when validating a single picking in a batch.
            if picking.batch_id and any(p.state != 'done' for p in picking.batch_id.picking_ids):
                picking.batch_id = None
            # If backorder were made and auto-batch is enabled, seek a batch for each of them with the selected criterias.
            to_assign_ids.update(picking.backorder_ids.ids)

        # If batch setting is enabled, auto-batch done pickings' backorders.
        if self.env.user.has_group('stock.group_stock_picking_batch'):
            # To avoid inconsistencies, all incorrect pickings must be removed before assigning backorder pickings
            assignable_pickings = self.env['stock.picking'].browse(to_assign_ids)
            for picking in assignable_pickings:
                picking._find_auto_batch()
            assignable_pickings.move_line_ids.with_context(skip_auto_waveable=True)._auto_wave()

    report_actions = self._get_autoprint_report_actions()
    if report_actions:
        return {
            'type': 'ir.actions.client',
            'tag': 'do_multi_print',
            'params': {
                'reports': report_actions,
            }
        }
    return True

def _pre_action_done_hook(self):
    for picking in self:
        has_quantity = False
        has_pick = False
        for move in picking.move_ids:
            if move.quantity:
                has_quantity = True
            if move.location_dest_usage == 'inventory':
                continue
            if move.picked:
                has_pick = True
            if has_quantity and has_pick:
                break
        if has_quantity and not has_pick:
            picking.move_ids.picked = True
    if not self.env.context.get('skip_backorder'):
        pickings_to_backorder = self._check_backorder()
        if pickings_to_backorder:
            return pickings_to_backorder._action_generate_backorder_wizard(show_transfers=self._should_show_transfers())
    return True

def _check_backorder(self):
    prec = self.env["decimal.precision"].precision_get("Product Unit")
    backorder_pickings = self.browse()
    for picking in self:
        if picking.picking_type_id.create_backorder != 'ask':
            continue
        if any(
                (move.product_uom_qty and not move.picked) or
                float_compare(move._get_picked_quantity(), move.product_uom_qty, precision_digits=prec) < 0
                for move in picking.move_ids
                if move.state != 'cancel'
        ):
            backorder_pickings |= picking
    return backorder_pickings

def get_inspections(cls, records, operation):
    pool = Pool()
    Inspection = pool.get('quality.inspection')

    records = [
        r for r in records if not r.quality_controlled_for(operation)]
    inspections = []
    if records:
        name = records[0].__name__
        assert len({r.__name__ for r in records}) == 1

        controls = cls.search([
                ('operations', 'in', f'{name}:{operation}'),
                ])
        for control in controls:
            for record in records:
                pattern = record.quality_control_pattern(operation)
                if control.match(pattern) and control.choose(record):
                    inspections.append(
                        Inspection.get_from_control(control, record))
    return inspections

def __setup__(cls):
    cls.number.search_unaccented = False
    cls.reference.search_unaccented = False
    super().__setup__()
    t = cls.__table__()
    cls._sql_indexes.update({
            Index(t, (Coalesce(t.reference, ''), Index.Similarity())),
            })
    cls._transitions |= {
        ('pending', 'passed'),
        ('pending', 'failed'),
        ('passed', 'failed'),
        ('passed', 'pending'),
        ('failed', 'passed'),
        ('failed', 'pending'),
        }
    cls._buttons.update({
            'pending': {
                'invisible': ~Eval('state').in_(['passed', 'failed']),
                'icon': 'tryton-back',
                'depends': ['state'],
                },
            'process': {
                'invisible': Eval('state') != 'pending',
                'icon': 'tryton-forward',
                'depends': ['state'],
                },
            'pass_': {
                'invisible': Eval('state') != 'failed',
                'icon': 'tryton-ok',
                'depends': ['state'],
                },
            'fail': {
                'invisible': Eval('state') != 'passed',
                'icon': 'tryton-cancel',
                'depends': ['state'],
                },
            })

def order_number(cls, tables):
    table, _ = tables[None]
    return [CharLength(table.number), table.number]

def on_change_control(self):
    if self.control:
        points = dict(self.points) if self.points is not None else {}
        points.update(
            (p.name, None) for p in self.control.points)
        self.points = points

def validate_points(self):
    points = {p.name: p.string for p in self.control.points}
    missing = points.keys() - (self.points or {}).keys()
    if missing:
        raise InspectionValidationError(
            gettext('quality.msg_quality_inspection_missing_point',
                inspection=self.rec_name,
                points=', '.join(points[m] for m in missing),
                ))

def check(self):
    for point in self.control.points:
        if not point.check(self.points.get(point.name)):
            return False
    return True

def view_attributes(cls):
    attributes = super().view_attributes() + [
        ('/tree', 'visual', If(Eval('state') == 'failed', 'danger', '')),
        ]
    if Transaction().context.get('inspect'):
        attributes.extend([
                ('//field[@name="control"]', 'readonly', 1),
                ('//*[@name="origin"]', 'invisible', 1),
                ('//page[@id="other"]', 'invisible', 1),
                ('//*[@name="state"]', 'invisible', 1),
                ('//group[@id="buttons"]', 'states', {'invisible': True}),
                ])

    return attributes

def pending(cls, inspections):
    cls.write(inspections, {
            'processed_at': None,
            })

def process(cls, inspections):
    for inspection in inspections:
        inspection.validate_points()
    cls.write([i for i in inspections if not i.processed_at], {
            'processed_at': dt.datetime.now(),
            })
    with cls.bulk_func('pass_') as pass_, \
            cls.bulk_func('fail') as fail:
        for inspection in inspections:
            if inspection.check():
                pass_.push(inspection)
            else:
                fail.push(inspection)

def fail(cls, inspections):
    pool = Pool()
    Alert = pool.get('quality.alert')
    alerts = []
    for inspection in inspections:
        if not inspection.alerts:
            alerts.append(inspection.get_alert())
    Alert.save(alerts)

def get_alert(self):
    pool = Pool()
    Alert = pool.get('quality.alert')
    return Alert(
        company=self.company,
        origin=self)

def preprocess_values(cls, mode, values):
    pool = Pool()
    Configuration = pool.get('quality.configuration')
    values = super().preprocess_values(mode, values)
    if mode == 'create' and not values.get('number'):
        company_id = values.get('company', cls.default_company())
        if company_id is not None:
            configuration = Configuration(1)
            if sequence := configuration.get_multivalue(
                    'inspection_sequence', company=company_id):
                values['number'] = sequence.get()
    return values

def check_modification(
        cls, mode, inspections, values=None, external=False):
    super().check_modification(
        mode, inspections, values=values, external=external)
    if mode == 'delete':
        for inspection in inspections:
            if inspection.state != 'pending':
                raise AccessError(gettext(
                        'quality.msg_inspection_delete_non_pending',
                        inspection=inspection.rec_name))

def copy(cls, inspections, default=None):
    default = default.copy() if default is not None else {}
    default.setdefault('number')
    default.setdefault('processed_by')
    default.setdefault('processed_at')
    default.setdefault('passed_by')
    default.setdefault('failed_by')
    return super().copy(inspections, default=default)

def preprocess_values(cls, mode, values):
    pool = Pool()
    Configuration = pool.get('quality.configuration')
    values = super().preprocess_values(mode, values)
    if mode == 'create' and not values.get('number'):
        company_id = values.get('company', cls.default_company())
        if company_id is not None:
            configuration = Configuration(1)
            if sequence := configuration.get_multivalue(
                    'alert_sequence', company=company_id):
                values['number'] = sequence.get()
    return values

def value_inspection(self, fields):
    inspection = self.store.inspections[0]
    values = {}
    for fieldname in fields:
        values[fieldname] = getattr(inspection, fieldname)

    if 'points' in fields:
        # Convert ImmutableDict to dict
        values['points'] = dict(values['points'] or {})
        for point in inspection.control.points:
            values['points'].setdefault(point.name)
    return values

@Override
@Transactional(rollbackOn = {Exception.class})
public void preFillOperations(QualityControl qualityControl, QualityProcess process)
    throws AxelorException {

  List<ControlPointModel> controlPointModelList = process.getControlPointModelList();
  List<ControlPointModel> optionalControlPointModelList =
      process.getOptionalControlPointModelList();
  List<QualityCorrectiveAction> qualityCorrectiveActionList =
      process.getQualityCorrectiveActionList();

  if (controlPointModelList != null) {
    qualityControl.getControlPointList().clear();

    for (ControlPointModel model : controlPointModelList) {
      ControlPoint point = new ControlPoint();
      this.createControlPointListItem(model, point, qualityControl);
      qualityControl.addControlPointListItem(point);
    }
  }

  if (optionalControlPointModelList != null) {
    qualityControl.getOptionalControlPointList().clear();

    for (ControlPointModel model : optionalControlPointModelList) {
      ControlPoint point = new ControlPoint();
      this.createControlPointListItem(model, point, qualityControl);
      qualityControl.addOptionalControlPointListItem(point);
    }
  }

  if (qualityCorrectiveActionList != null) {
    qualityControl.getQualityCorrectiveActionList().clear();

    for (QualityCorrectiveAction qualityCorrectiveAction : qualityCorrectiveActionList) {
      qualityCorrectiveAction =
          Beans.get(QualityCorrectiveActionRepository.class).copy(qualityCorrectiveAction, true);
      qualityControl.addQualityCorrectiveActionListItem(qualityCorrectiveAction);
    }
  }
}

@Override
@Transactional
public void preFillOperationsFromOptionals(
    QualityControl qualityControl, List<ControlPoint> optionalControlPointList) {

  for (ControlPoint optionalControlPoint : optionalControlPointList) {
    optionalControlPoint = controlPointRepo.copy(optionalControlPoint, true);
    optionalControlPoint.setOptionalQualityControl(null);
    qualityControl.addControlPointListItem(optionalControlPoint);
  }

  Beans.get(QualityControlRepository.class).save(qualityControl);
}

def validate_with_previous_doc(self):
	super().validate_with_previous_doc(
		{
			"Sales Order": {
				"ref_dn_field": "against_sales_order",
				"compare_fields": [
					["customer", "="],
					["company", "="],
					["project", "="],
					["currency", "="],
				],
			},
			"Sales Order Item": {
				"ref_dn_field": "so_detail",
				"compare_fields": [["item_code", "="], ["uom", "="], ["conversion_factor", "="]],
				"is_child_table": True,
				"allow_duplicate_prev_row_id": True,
			},
			"Sales Invoice": {
				"ref_dn_field": "against_sales_invoice",
				"compare_fields": [
					["customer", "="],
					["company", "="],
					["project", "="],
					["currency", "="],
				],
			},
			"Sales Invoice Item": {
				"ref_dn_field": "si_detail",
				"compare_fields": [["item_code", "="], ["uom", "="], ["conversion_factor", "="]],
				"is_child_table": True,
				"allow_duplicate_prev_row_id": True,
			},
		}
	)

	if (
		cint(frappe.get_single_value("Selling Settings", "maintain_same_sales_rate"))
		and not self.is_return
		and not self.is_internal_customer
	):
		self.validate_rate_with_reference_doc(
			[
				["Sales Order", "against_sales_order", "so_detail"],
				["Sales Invoice", "against_sales_invoice", "si_detail"],
			]
		)

def validate_references(self):
	self.validate_sales_order_references()
	self.validate_sales_invoice_references()

def validate_sales_order_references(self):
	self._validate_dependent_item_fields(
		"against_sales_order", "so_detail", _("References to Sales Orders are Incomplete")
	)

def validate_sales_invoice_references(self):
	if self.is_return:
		return

	self._validate_dependent_item_fields(
		"against_sales_invoice", "si_detail", _("References to Sales Invoices are Incomplete")
	)

def _validate_dependent_item_fields(self, field_a: str, field_b: str, error_title: str):
	errors = []
	for item in self.items:
		missing_label = None
		if item.get(field_a) and not item.get(field_b):
			missing_label = item.meta.get_label(field_b)
		elif item.get(field_b) and not item.get(field_a):
			missing_label = item.meta.get_label(field_a)

		if missing_label and missing_label != "No Label":
			errors.append(
				_("The field {0} in row {1} is not set").format(
					frappe.bold(_(missing_label)), frappe.bold(item.idx)
				)
			)

	if errors:
		frappe.throw("<br>".join(errors), title=error_title)

def validate_proj_cust(self):
	"""check for does customer belong to same project as entered.."""
	if self.project and self.customer:
		res = frappe.db.sql(
			"""select name from `tabProject`
			where name = %s and (customer = %s or
				ifnull(customer,'')='')""",
			(self.project, self.customer),
		)
		if not res:
			frappe.throw(
				_("Customer {0} does not belong to project {1}").format(self.customer, self.project)
			)

def validate_warehouse(self):
	super().validate_warehouse()

	for d in self.get_item_list():
		if not d["warehouse"] and frappe.get_cached_value("Item", d["item_code"], "is_stock_item") == 1:
			frappe.throw(_("Warehouse required for stock Item {0}").format(d["item_code"]))

def update_current_stock(self):
	if not (self.get("_action") and self._action != "update_after_submit"):
		return

	warehouse_item_codes = {}
	for d in self.get("items") + self.get("packed_items"):
		warehouse_item_codes.setdefault(d.warehouse, set()).add(d.item_code)

	if not warehouse_item_codes:
		return

	bin_map = {}
	for warehouse, item_codes in warehouse_item_codes.items():
		for b in frappe.get_all(
			"Bin",
			filters={"item_code": ["in", item_codes], "warehouse": warehouse},
			fields=["item_code", "actual_qty", "projected_qty"],
		):
			bin_map[(b.item_code, warehouse)] = b

	for d in self.get("items"):
		bin_data = bin_map.get((d.item_code, d.warehouse))
		d.actual_qty = bin_data.actual_qty if bin_data else None

	for d in self.get("packed_items"):
		bin_data = bin_map.get((d.item_code, d.warehouse))
		if bin_data:
			d.actual_qty = flt(bin_data.actual_qty)
			d.projected_qty = flt(bin_data.projected_qty)

def check_credit_limit(self):
	from erpnext.selling.doctype.customer.customer import check_credit_limit

	if self.per_billed == 100:
		return

	extra_amount = 0
	validate_against_credit_limit = False
	bypass_credit_limit_check_at_sales_order = cint(
		frappe.db.get_value(
			"Customer Credit Limit",
			filters={"parent": self.customer, "parenttype": "Customer", "company": self.company},
			fieldname="bypass_credit_limit_check",
		)
	)

	if bypass_credit_limit_check_at_sales_order:
		for d in self.get("items"):
			if not d.against_sales_invoice:
				validate_against_credit_limit = True
				extra_amount = self.base_grand_total
				break
	else:
		for d in self.get("items"):
			if not (d.against_sales_order or d.against_sales_invoice):
				validate_against_credit_limit = True
				break

	if validate_against_credit_limit:
		check_credit_limit(
			self.customer, self.company, bypass_credit_limit_check_at_sales_order, extra_amount
		)

